import React from 'react';
import PropTypes from 'prop-types';
import Card from '../ui/Card';

/**
 * RecentCheckInOut Component
 * 
 * Displays recent check-in and check-out times for the last 7 days
 * with color-coded status indicators.
 * 
 * @param {Array} records - Array of attendance records
 */
const RecentCheckInOut = ({ records = [] }) => {
  // Get the last 7 days of records (sorted by date descending)
  const recentRecords = [...records]
    .sort((a, b) => new Date(b.date) - new Date(a.date))
    .slice(0, 7);

  // Get status badge color
  const getStatusBadge = (status) => {
    switch (status) {
      case 'Present':
        return 'bg-green-100 text-green-800 dark:bg-green-900/30 dark:text-green-400';
      case 'Absent':
        return 'bg-red-100 text-red-800 dark:bg-red-900/30 dark:text-red-400';
      case 'Late':
        return 'bg-yellow-100 text-yellow-800 dark:bg-yellow-900/30 dark:text-yellow-400';
      case 'Half Day':
        return 'bg-orange-100 text-orange-800 dark:bg-orange-900/30 dark:text-orange-400';
      default:
        return 'bg-gray-100 text-gray-800 dark:bg-gray-900/30 dark:text-gray-400';
    }
  };

  // Get status icon
  const getStatusIcon = (status) => {
    switch (status) {
      case 'Present':
        return 'check_circle';
      case 'Absent':
        return 'cancel';
      case 'Late':
        return 'schedule';
      case 'Half Day':
        return 'timelapse';
      default:
        return 'help_outline';
    }
  };

  // Format date to readable format
  const formatDate = (dateStr) => {
    const date = new Date(dateStr);
    const today = new Date();
    const yesterday = new Date(today);
    yesterday.setDate(yesterday.getDate() - 1);

    if (date.toDateString() === today.toDateString()) {
      return 'Today';
    } else if (date.toDateString() === yesterday.toDateString()) {
      return 'Yesterday';
    } else {
      return date.toLocaleDateString('en-US', { 
        weekday: 'short', 
        month: 'short', 
        day: 'numeric' 
      });
    }
  };

  if (recentRecords.length === 0) {
    return (
      <Card title="Recent Check-In/Out" icon="access_time">
        <div className="text-center py-8">
          <span className="material-icons text-subtext-light text-5xl mb-4">event_busy</span>
          <p className="text-text-light dark:text-text-dark">
            No recent attendance records available.
          </p>
        </div>
      </Card>
    );
  }

  return (
    <Card title="Recent Check-In/Out" icon="access_time">
      <div className="space-y-3">
        {recentRecords.map((record) => (
          <div
            key={record.date}
            className="flex items-center justify-between p-4 rounded-lg bg-background-light dark:bg-background-dark hover:shadow-sm transition-shadow"
          >
            {/* Date and Status */}
            <div className="flex items-center gap-4 flex-1">
              <div className="flex-shrink-0">
                <div className="w-12 h-12 rounded-full bg-primary/10 flex items-center justify-center">
                  <span className="material-icons text-primary">
                    {getStatusIcon(record.status)}
                  </span>
                </div>
              </div>

              <div className="flex-1 min-w-0">
                <div className="flex items-center gap-2 mb-1">
                  <p className="text-sm font-semibold text-heading-light dark:text-heading-dark">
                    {formatDate(record.date)}
                  </p>
                  <span className={`px-2 py-1 rounded-full text-xs font-medium ${getStatusBadge(record.status)}`}>
                    {record.status}
                  </span>
                </div>
                <p className="text-xs text-subtext-light">
                  {new Date(record.date).toLocaleDateString('en-US', { 
                    year: 'numeric', 
                    month: 'long', 
                    day: 'numeric' 
                  })}
                </p>
              </div>
            </div>

            {/* Check-In/Out Times */}
            <div className="flex items-center gap-6 text-sm">
              <div className="text-center">
                <p className="text-xs text-subtext-light mb-1">Check In</p>
                <p className="font-semibold text-text-light dark:text-text-dark">
                  {record.checkIn || '--:--'}
                </p>
              </div>

              <div className="text-center">
                <p className="text-xs text-subtext-light mb-1">Check Out</p>
                <p className="font-semibold text-text-light dark:text-text-dark">
                  {record.checkOut || '--:--'}
                </p>
              </div>

              {record.workHours !== undefined && (
                <div className="text-center">
                  <p className="text-xs text-subtext-light mb-1">Hours</p>
                  <p className="font-semibold text-primary">
                    {record.workHours}h
                  </p>
                </div>
              )}
            </div>
          </div>
        ))}
      </div>
    </Card>
  );
};

RecentCheckInOut.propTypes = {
  records: PropTypes.arrayOf(PropTypes.shape({
    date: PropTypes.string.isRequired,
    checkIn: PropTypes.string,
    checkOut: PropTypes.string,
    status: PropTypes.oneOf(['Present', 'Absent', 'Late', 'Half Day']).isRequired,
    workHours: PropTypes.number
  }))
};

export default RecentCheckInOut;
